import json
def enclosed_fill(g):
    out=[r[:] for r in g]
    H,W=len(g),len(g[0])
    # flood fill background from borders; holes = non-zero cells not reachable... actually fill zero cells enclosed by nonzero
    seen=[[False]*W for _ in range(H)]
    from collections import deque
    dq=deque()
    for r in range(H):
        for c in [0,W-1]:
            if not seen[r][c] and g[r][c]==0:
                seen[r][c]=True; dq.append((r,c))
    for r in range(0,H):
        if not seen[r][0]: seen[r][0]=True; dq.append((r,0))
    for r in range(H-1,-1,-1):
        for c in [0,W-1]:
            if not seen[r][c] and g[r][c]==0:
                seen[r][c]=True; dq.append((r,c))
    for c in range(W):
        for r in [0,H-1]:
            if not seen[r][c] and g[r][c]==0:
                seen[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]==0:
                seen[nr][nc]=True; dq.append((nr,nc))
    # enclosed zero cells: adjacent to non-zero or fully surrounded
    res=out[:]
    for r in range(H):
        for c in range(W):
            if g[r][c]==0 and not seen[r][c]:
                # check if enclosed by non-zero neighbors
                nb=[g[r+dr][c+dc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W]
                if any(x!=0 for x in nb):
                    res[r][c]=nb[0] if nb[0]!=0 else (nb[1] if nb[1]!=0 else nb[2])
    return res
